"use strict";(()=>{const o=document.querySelector(".product-shell");if(!o)return;const u=e=>"Rs "+new Intl.NumberFormat("en-PK").format(e),m=Number(o.dataset.shipping||300),i=document.querySelector("#bundle"),d=document.querySelector("#quantity"),y=document.querySelector("#quantity-value"),q=document.querySelector("#package-name"),p=document.querySelector("#package-copy"),S=document.querySelector("#unit-label"),g=document.querySelector("#summary-name"),b=document.querySelector("#summary-subtotal"),k=document.querySelector("#summary-total"),a=[...document.querySelectorAll("[data-package]")];let n=a.find(e=>e.classList.contains("active"))||a[0],t=1;function c(){const e=Number(n.dataset.price),r=n.dataset.name,v=Number(n.dataset.units),s=e*t;a.forEach(l=>l.classList.toggle("active",l===n)),i.value=n.dataset.package,d.value=String(t),y.textContent=String(t),q.textContent=r,p.textContent=n.dataset.copy,S.textContent=v+" \xD7 100 ml",g.textContent=r+" \xD7 "+t,b.textContent=u(s),k.textContent=u(s+m)}a.forEach(e=>e.addEventListener("click",()=>{n=e,c()})),document.querySelector("#quantity-minus").addEventListener("click",()=>{t=Math.max(1,t-1),c()}),document.querySelector("#quantity-plus").addEventListener("click",()=>{t=Math.min(10,t+1),c()}),c()})();
